window.kbPageData["views/entry/k-497528c798c6df08"] = {"key":"entry/k-497528c798c6df08","state":{"route":"entry/k-497528c798c6df08"},"node":{"id":"k-497528c798c6df08","mode":"k","title":"冒名婚姻登记的确认无效与补救","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["冒名婚姻登记行政行为的无效认定及错误信息删除"],"qs":["江苏 2023 B类 行测#20"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"冒用他人身份致使结婚登记对象错误，构成重大且明显违法的，人民法院依法判决确认登记行为无效。错误登记信息持续损害被冒名人权益的，法院可以同时判令登记机关采取删除错误信息等补救措施。","review":{"definition":"冒用他人身份致使结婚登记对象错误，构成重大且明显违法的，人民法院依法判决确认登记行为无效。错误登记信息持续损害被冒名人权益的，法院可以同时判令登记机关采取删除错误信息等补救措施。","explanation":"第20题中，实际到场登记的是梁某，陈某的身份却被记入登记系统，导致陈某本人无法办理结婚登记。先前的离婚判决并未撤销原结婚登记，法院仍可在行政诉讼中审查该登记行为。南通开发区法院尚某案也有先前的离婚判决。该案主文确认登记无效，并依《行政诉讼法》第七十六条责令如东县民政局在判决生效后六十日内删除错误登记信息。D项中的删除应理解为法院判令登记机关实施的个案补救。","references":[{"source":"web-6e4b58470db61c7f","location":"裁判理由第二、四部分及判决主文第二、三项","quote":"对原告尚某的错误婚姻登记信息采取删除的补救措施"},{"source":"web-e498a67eed717441","location":"第七十五条、第七十六条","quote":"可以同时判决责令被告采取补救措施"},{"source":"web-47f9e3dd8cd81c8c","location":"第九十九条第三项","quote":"行政行为的内容客观上不可能实施"}],"evidence":"法院应判决确认M县民政局的登记无效并删除错误登记信息","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2023 B类 行测#20":{"paper":"江苏 2023 B类 行测","n":20,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",3],"asrc":["b08f2713d73015eac675.pdf",8],"card":"a980fa5fcb5dfb5bac46689a","links":[{"id":"k-497528c798c6df08","role":"直接考查","why":"真实结婚人和登记身份不一致，解析据行政行为内容客观上不可能实施认定登记重大且明显违法。"}]}},"terms":{},"references":{"web-6e4b58470db61c7f":{"name":"江苏省南通经济技术开发区人民法院（2020）苏0691行初325号行政判决书（转载全文）","url":"https://www.sohu.com/a/606407249_121123711"},"web-e498a67eed717441":{"name":"《中华人民共和国行政诉讼法》（2017年修正）","url":"https://gdca.miit.gov.cn/zwgk/zcwj/flfg/art/2020/art_58ff765df1624075b6da5507fe438b38.html"},"web-47f9e3dd8cd81c8c":{"name":"《最高人民法院关于适用〈中华人民共和国行政诉讼法〉的解释》","url":"https://www.court.gov.cn/zixun/xiangqing/80342.html"}},"topics":[],"units":{"k-497528c798c6df08":[["江苏 2023 B类 行测#20"]]}};
